const require_serde_api = require('./serde_api.cjs');

//#region src/interface.ts
function makeHandlerDescriptor(inputSerde, outputSerde, shared, opts) {
	return {
		_inputSerde: inputSerde,
		_outputSerde: outputSerde,
		_shared: shared,
		_description: opts?.description,
		_metadata: opts?.metadata
	};
}
/**
* Declare a service interface (contract) as a runtime value carrying handler
* names + input/output serdes, without an implementation. Place it in a shared
* package that both the server (via `implement()`) and callers (via
* `ctx.serviceClient(iface)` / `connect().serviceClient(iface)`) import.
*
* @example
* ```ts
* const greeter = iface.service("greeter", {
*   greet: iface.schemas({ input: GreetReq, output: GreetRes }),
*   ping:  iface.json<void, string>(),
* });
* ```
*/
const iface = {
	service: function(name, handlers, opts) {
		return {
			name,
			_kind: "service",
			_handlers: handlers,
			_description: opts?.description,
			_metadata: opts?.metadata
		};
	},
	object: function(name, handlers, opts) {
		return {
			name,
			_kind: "object",
			_handlers: handlers,
			_description: opts?.description,
			_metadata: opts?.metadata
		};
	},
	workflow: function(name, handlers, opts) {
		return {
			name,
			_kind: "workflow",
			_handlers: handlers,
			_description: opts?.description,
			_metadata: opts?.metadata
		};
	},
	json: function(opts) {
		return makeHandlerDescriptor(void 0, void 0, false, opts);
	},
	serdes: function(opts) {
		return makeHandlerDescriptor(opts.input, opts.output, false, opts);
	},
	schemas: function(opts) {
		return makeHandlerDescriptor(opts.input ? require_serde_api.serde.schema(opts.input) : void 0, opts.output ? require_serde_api.serde.schema(opts.output) : void 0, false, opts);
	},
	shared: {
		json: function(opts) {
			return makeHandlerDescriptor(void 0, void 0, true, opts);
		},
		serdes: function(opts) {
			return makeHandlerDescriptor(opts.input, opts.output, true, opts);
		},
		schemas: function(opts) {
			return makeHandlerDescriptor(opts.input ? require_serde_api.serde.schema(opts.input) : void 0, opts.output ? require_serde_api.serde.schema(opts.output) : void 0, true, opts);
		}
	}
};

//#endregion
exports.iface = iface;
exports.makeHandlerDescriptor = makeHandlerDescriptor;